const raw = $input.first().json.output ?? $input.first().json.text ?? '';
let d;
try {
  const s = typeof raw === 'string' ? raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim() : raw;
  d = typeof s === 'string' ? JSON.parse(s) : s;
  if (!d || typeof d !== 'object') throw new Error('not object');
} catch {
  return [{json:{responseType:'text',answer:String(raw || 'AI 沒有回傳可解析的內容')}}];
}
const answer=String(d.answer||'');
if(d.responseType==='dashboard_panel' && d.panel){return [{json:{responseType:'dashboard_panel',answer,dashboardUid:d.panel.dashboardUid,panelId:d.panel.panelId,title:d.panel.title||'Grafana Panel',from:d.panel.from||'now-15m',to:d.panel.to||'now',variables:d.panel.variables||{}}}];}
if(d.responseType==='metric_chart' && d.chart){return [{json:{responseType:'metric_chart',answer,datasourceUid:d.chart.datasourceUid,query:d.chart.query,title:d.chart.title||'Metrics 圖表',from:d.chart.from||'now-15m',to:d.chart.to||'now'}}];}
return [{json:{responseType:'text',answer:answer||'沒有取得可確認的查詢結果。'}}];

const d=$input.first().json;
const BASE='https://utckfk8sgrafana.k8skf.unimicron.com';
const uid=String(d.dashboardUid||'').trim(); const panelId=Number(d.panelId);
if(!/^[a-zA-Z0-9_-]+$/.test(uid)||!Number.isSafeInteger(panelId)||panelId<=0)throw Error('Dashboard UID 或 Panel ID 無效');
const from=String(d.from||'now-15m'),to=String(d.to||'now');
function ms(v){if(v==='now')return Date.now(); const m=/^now-(\d+)([smhdw])$/.exec(v); if(m)return Date.now()-Number(m[1])*({s:1e3,m:6e4,h:36e5,d:864e5,w:6048e5}[m[2]]); if(!/(Z|[+-]\d\d:\d\d)$/i.test(v))throw Error('絕對時間需帶時區'); const t=Date.parse(v);if(!Number.isFinite(t))throw Error('時間錯誤');return t;}
const begin=ms(from),end=ms(to); if(end<=begin||end-begin>7*864e5||end>Date.now()+6e4)throw Error('時間範圍不合法');
const vars=d.variables||{};
if(typeof vars!=='object'||vars===null||Array.isArray(vars)||Object.keys(vars).length>30)throw Error('variables 不合法');
const p=new URLSearchParams({orgId:'1',panelId:String(panelId),from,to,width:'1200',height:'650',tz:'Asia/Taipei'});
const q=new URLSearchParams({orgId:'1',from,to,timezone:'Asia/Taipei'});
for(const [rawKey,value] of Object.entries(vars)){const k=rawKey.replace(/^var-/,'');if(!/^[A-Za-z_][A-Za-z0-9_-]*$/.test(k)||typeof value!=='string'||value.length>300)throw Error('variable 不合法: '+k);p.append('var-'+k,value);q.append('var-'+k,value);}
return [{json:{...d,renderUrl:`${BASE}/render/d-solo/${uid}?${p.toString()}`,dashboardUrl:`${BASE}/d/${uid}?${q.toString()}`}}];

